class Solution {
    public int longestConsecutive(int[] nums) {
        Set<Integer> seen = new HashSet<>();
        for (int x : nums) {
            seen.add(x);
        }
        int best = 0;
        for (int x : seen) {
            if (seen.contains(x - 1)) {
                continue;
            }
            int y = x + 1;
            while (seen.contains(y)) {
                y++;
            }
            best = Math.max(best, y - x);
        }
        return best;
    }
}

