class Solution:
    def findAnagrams(self, s: str, p: str) -> list:
        n, m = len(s), len(p)
        if n < m:
            return []
        cnt = [0] * 26
        for ch in p:
            cnt[ord(ch) - ord('a')] += 1
        res = []
        for i in range(n):
            cnt[ord(s[i]) - ord('a')] -= 1
            if i >= m:
                cnt[ord(s[i - m]) - ord('a')] += 1
            if all(v == 0 for v in cnt):
                res.append(i - m + 1)
        return res

