class Solution {
public:
    vector<int> findAnagrams(string s, string p) {
        int n = s.size(), m = p.size();
        vector<int> res;
        if (n < m) return res;
        vector<int> cnt(26, 0);
        for (char ch : p) cnt[ch - 'a']++;
        for (int i = 0; i < n; ++i) {
            cnt[s[i] - 'a']--;
            if (i >= m) cnt[s[i - m] - 'a']++;
            bool ok = true;
            for (int v : cnt) {
                if (v != 0) { ok = false; break; }
            }
            if (ok) res.push_back(i - m + 1);
        }
        return res;
    }
};

