class Solution {
public:
    string minWindow(string s, string t) {
        unordered_map<char, int> need;
        for (char c : t) {
            need[c]++;
        }
        int missing = (int)t.size();
        int left = 0, start = 0;
        int minLen = (int)s.size() + 1;
        for (int right = 0; right < (int)s.size(); right++) {
            if (need[s[right]] > 0) {
                missing--;
            }
            need[s[right]]--;
            while (missing == 0) {
                if (right - left + 1 < minLen) {
                    minLen = right - left + 1;
                    start = left;
                }
                need[s[left]]++;
                if (need[s[left]] > 0) {
                    missing++;
                }
                left++;
            }
        }
        return minLen > (int)s.size() ? "" : s.substr(start, minLen);
    }
};

