class Solution:
    def mergeKLists(self, lists):
        if not lists:
            return None
        return self._mergeRange(lists, 0, len(lists) - 1)

    def _mergeRange(self, lists, left, right):
        if left == right:
            return lists[left]
        mid = (left + right) // 2
        l1 = self._mergeRange(lists, left, mid)
        l2 = self._mergeRange(lists, mid + 1, right)
        return self._mergeTwo(l1, l2)

