            indegree[p[0]]++;
        }
        Queue<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < numCourses; i++) if (indegree[i] == 0) queue.add(i);
        int taken = 0;
        while (!queue.isEmpty()) {
            int node = queue.poll();
            taken++;
            for (int nxt : graph.get(node)) {
                if (--indegree[nxt] == 0) queue.add(nxt);
            }
        }
        return taken == numCourses;
    }
}

