class Solution:
    def partition(self, s):
        n = len(s)
        pal = [[False]*n for _ in range(n)]
        for l in range(n-1,-1,-1):
            for r in range(l,n):
                pal[l][r] = s[l]==s[r] and (r-l<2 or pal[l+1][r-1])
        ans,path = [],[]
        def dfs(l):
            if l == n:
                ans.append(path[:]); return
            for r in range(l,n):
                if pal[l][r]:
                    path.append(s[l:r+1]); dfs(r+1); path.pop()
        dfs(0)
        return ans

