class Solution {
public:
    vector<vector<string>> solveNQueens(int n) {
        vector<vector<string>> result;
        vector<int> queens(n, -1);
        vector<bool> cols(n, false), diag1(2 * n + 1, false), diag2(2 * n + 1, false);
        backtrack(0, n, queens, cols, diag1, diag2, result);
        return result;
    }

private:
    void backtrack(int row, int n, vector<int>& queens, vector<bool>& cols,
                   vector<bool>& diag1, vector<bool>& diag2, vector<vector<string>>& result) {
        if (row == n) {
            vector<string> board;
            for (int r = 0; r < n; ++r) {
                string line(n, '.');
                line[queens[r]] = 'Q';
                board.push_back(line);
            }
            result.push_back(board);
            return;
        }
        for (int col = 0; col < n; ++col) {
            int d1 = row - col + n;
            int d2 = row + col;
            if (cols[col] || diag1[d1] || diag2[d2]) continue;
            queens[row] = col;
            cols[col] = diag1[d1] = diag2[d2] = true;
            backtrack(row + 1, n, queens, cols, diag1, diag2, result);
            cols[col] = diag1[d1] = diag2[d2] = false;
        }
    }
};

