                if ((m + n) % 2 == 1) {
                    return (double) Math.max(aLeft, bLeft);
                }
                return ((long) Math.max(aLeft, bLeft) + Math.min(aRight, bRight)) / 2.0;
            } else if (aLeft > bRight) {
                hi = i - 1;
            } else {
                lo = i + 1;
            }
        }
        throw new IllegalArgumentException();
    }
}

